import {ownerSampleMode} from './experience-mode.js?v=5.5.1';
import {normalizeFulfillment} from './order-details.js?v=5.5.1';
import {MENU} from './menu.js?v=5.5.1';
export let STORAGE_KEY='modu-jumo-demo-v2';
export function configureState(key){STORAGE_KEY=key;}
export function replaceState(s){return writeState(s);}
const uid=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2)}`;
const previewMode=typeof location!=='undefined'&&new URLSearchParams(location.search).get('preview')==='1'&&new URLSearchParams(location.search).get('sample')!=='owner'&&!ownerSampleMode(typeof document==='undefined'?'guest':document.body.dataset.role,location.search);
let previewState=null;
const blank=()=>({version:2,store:{name:'주모',address:'',country:'VN',phone:'',email:'',website:'',photos:[],perVisit:15,perDay:100},menu:{},sessions:[],orders:[],events:[],activeSession:null});
export function readState(){if(previewMode){if(!previewState){const init=blank();try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved?.version===2){init.store={...init.store,...saved.store};init.menu=saved.menu||{}}}catch{}previewState=JSON.stringify(init);}return JSON.parse(previewState)}try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY));if(s?.version===2&&Array.isArray(s.sessions)&&Array.isArray(s.orders)&&Array.isArray(s.events))return s}catch{}return blank()}
export function writeState(s){s.events=s.events.slice(-400);if(previewMode)previewState=JSON.stringify(s);else localStorage.setItem(STORAGE_KEY,JSON.stringify(s));globalThis.dispatchEvent?.(new Event('modu-state'));return s}
export function mutate(fn){const s=readState();const result=fn(s);writeState(s);return result}
export function event(s,type,sessionId,detail={}){s.events.push({id:uid('evt'),type,sessionId,detail,at:new Date().toISOString(),reviewed:false});}
export const menuFor=s=>(s.items||MENU).map(x=>({...x,price:Number.isFinite(s.menu?.[x.id]?.price)?s.menu[x.id].price:x.price,available:s.menu?.[x.id]?.available!==false}));
export function ensureSession(table=3,lang='ko',force=false){return mutate(s=>{let v=s.sessions.find(x=>x.id===s.activeSession);if(force||!v||v.table!==table){v={id:uid('visit'),table,lang,nickname:'',consent:false,at:new Date().toISOString(),cart:{},messages:[],games:{},coupons:[],chatCount:0};s.sessions.push(v);s.activeSession=v.id;event(s,'eventVisit',v.id,{table,lang});}else v.lang=lang;return v.id})}
export const sessionOf=(s,id)=>s.sessions.find(x=>x.id===id);
export function updateCart(id,itemId,delta){return mutate(s=>{const v=sessionOf(s,id),item=menuFor(s).find(x=>x.id===itemId);if(!v||!item||(delta>0&&!item.available))throw new Error('soldOut');const qty=(v.cart[itemId]||0)+delta;if(qty>20)throw new Error('maxQty');if(qty<=0)delete v.cart[itemId];else v.cart[itemId]=qty;return v.cart})}
export const cartTotal=(s,id)=>menuFor(s).reduce((n,x)=>n+x.price*(sessionOf(s,id)?.cart[x.id]||0),0);
export const cartQuote=(s,id)=>menuFor(s).filter(x=>sessionOf(s,id)?.cart[x.id]).map(x=>`${x.id}:${sessionOf(s,id).cart[x.id]}:${x.price}:${x.available}`).sort().join('|');
export function placeOrder(id,requestId,expectedQuote,details){return mutate(s=>{const existing=s.orders.find(o=>o.requestId===requestId&&o.sessionId===id);if(existing)return existing;if(expectedQuote!==undefined&&expectedQuote!==cartQuote(s,id))throw new Error('priceChanged');const v=sessionOf(s,id);if(!v)throw new Error('emptyCart');const menu=menuFor(s),lines=Object.entries(v.cart).map(([itemId,quantity])=>{const x=menu.find(i=>i.id===itemId);if(!x?.available)throw new Error('soldOut');if(!Number.isInteger(quantity)||quantity<1||quantity>20)throw new Error('maxQty');return {itemId,quantity,unitPrice:x.price};});if(!lines.length)throw new Error('emptyCart');const fulfillment=normalizeFulfillment(details);const order={id:uid('order'),number:Math.max(0,...s.orders.map(o=>Number(o.number)||0))+1,requestId,sessionId:id,table:fulfillment.channel==='dine-in'?fulfillment.table:null,fulfillment,lang:v.lang,at:new Date().toISOString(),status:'pending',payment:'unpaid',lines,total:lines.reduce((n,x)=>n+x.quantity*x.unitPrice,0)};s.orders.push(order);v.cart={};event(s,'eventOrder',id,{orderId:order.id,total:order.total});return order})}
export function setOrderState(orderId,next,payment=false){return mutate(s=>{const o=s.orders.find(o=>o.id===orderId);if(!o)return;const allowed={pending:'accepted',accepted:'preparing',preparing:'ready',ready:'completed'};if(payment){if(o.payment==='paid')return;o.payment='paid';}else{if(allowed[o.status]!==next)return;o.status=next;}event(s,'eventStatus',o.sessionId,{orderId,next:payment?'paid':next})})}
export function quota(s,id){const v=sessionOf(s,id);const day=new Date().toISOString().slice(0,10);const daily=s.sessions.reduce((n,x)=>n+x.messages.filter(m=>m.at.startsWith(day)&&m.inScope).length,0);return Math.max(0,Math.min(s.store.perVisit-v.chatCount,s.store.perDay-daily))}
export function recordChat(id,text,key,lang,inScope=true,answerData=null){return mutate(s=>{const v=sessionOf(s,id);if(!v)return;if(inScope&&quota(s,id)===0){key='limitReached';inScope=false;answerData=null;}if(inScope)v.chatCount++;v.messages.push({id:uid('msg'),text:text.slice(0,400),key,lang,inScope,answerData,at:new Date().toISOString()});event(s,key==='offTopic'?'eventOffTopic':key==='limitReached'?'eventLimit':key==='replyComplaint'?'complaint':'eventChat',id,{question:text.slice(0,400),reply:key,lang});return key})}
export function addRequest(id,text=''){return mutate(s=>event(s,text?'complaint':'eventStaff',id,{question:text.slice(0,400)}))}
export function updateProfile(id,nickname,consent,lang){return mutate(s=>{const v=sessionOf(s,id);v.nickname=consent?nickname.trim().slice(0,30):'';v.consent=consent;v.lang=lang;event(s,'eventProfile',id,{consent})})}
export function randomInt(max){if(!Number.isInteger(max)||max<1)throw new Error('bad_random_range');const limit=Math.floor(0x100000000/max)*max;let v;do{v=crypto.getRandomValues(new Uint32Array(1))[0]}while(v>=limit);return v%max}
export function playGame(id,kind,choice,draw=randomInt){return mutate(s=>{const v=sessionOf(s,id);if(v.games[kind])throw new Error('alreadyPlayed');let outcome,reward=null,opponent=null,index=null;if(kind==='rps'){if(!['rock','paper','scissors'].includes(choice))throw new Error('invalid');opponent=['rock','paper','scissors'][draw(3)];const win={rock:'scissors',paper:'rock',scissors:'paper'};outcome=choice===opponent?'draw':win[choice]===opponent?'win':'lose';if(outcome==='win')reward='rewardSnack';}else if(kind==='roulette'){index=draw(4);reward=['rewardTea','rewardSweet','rewardSnack',null][index];outcome=reward?'win':'noPrize';}else throw new Error('invalid');let capped=false;if(reward){if(v.coupons.some(c=>c.source!=='points'))capped=true;else{v.coupons.push({id:uid('coupon'),code:'JM-'+uid('').slice(-6).toUpperCase(),reward,used:false,at:new Date().toISOString()});event(s,'eventReward',id,{reward});}}const result={kind,choice,opponent,index,outcome,reward,capped,at:new Date().toISOString()};v.games[kind]=result;event(s,'eventGame',id,result);return result})}
export function redeemCoupon(id,couponId){return mutate(s=>{const v=sessionOf(s,id),c=v?.coupons.find(c=>c.id===couponId);if(!c||c.used)return false;c.used=true;c.usedAt=new Date().toISOString();event(s,'eventStatus',id,{couponId,state:'couponUsed'});return true})}
export function markReviewed(eventId){return mutate(s=>{const e=s.events.find(x=>x.id===eventId);if(e)e.reviewed=true})}
export function posPayload(s,order=s.orders.at(-1)){if(!order)return {schemaVersion:'1.0',mode:'demo',event:'order.created',note:'Create a demo order to populate this payload.'};return {schemaVersion:'1.0',mode:'demo',event:'order.created',eventId:'evt-'+order.id,idempotencyKey:order.requestId,storeId:'jumo-demo',occurredAt:order.at,data:{orderId:order.id,table:order.table,fulfillment:order.fulfillment||null,currency:'VND',items:order.lines,amount:order.total,orderStatus:order.status,paymentStatus:order.payment}}}
